namespace CampaignDemo {
 public static class LocalPvpReplication {
  static string StableJson(UnityEngine.Object obj){return obj==null?"":Regex.Replace(JsonUtility.ToJson(obj),"\"instanceID\":-?[0-9]+","\"instanceID\":0");}
  public static string Fingerprint(BattleWorld world){var text=new StringBuilder("shared-tactical-v3|");text.Append(StableJson(world.setup.roadMap.definition)).Append(StableJson(world.setup.freeMarchMap.definition)).Append(StableJson(world.campaign==null?null:world.campaign.rules));
   var units=new List<BattleUnit>(world.units);units.Sort((a,b)=>string.CompareOrdinal(a.unitId,b.unitId));foreach(var u in units)text.Append(u.unitId).Append(u.ownerId).Append(JsonUtility.ToJson(u.transform.position)).Append(StableJson(u.combatDefinition)).Append(StableJson(u.GetComponent<ArmyRoadMover>().definition));
   var points=new List<RecoveryPoint>(world.points);points.Sort((a,b)=>string.CompareOrdinal(a.pointId,b.pointId));foreach(var p in points)text.Append(p.pointId).Append(p.ownerId).Append(JsonUtility.ToJson(p.transform.position)).Append(p.resourceStock.ToString("R",System.Globalization.CultureInfo.InvariantCulture));
   using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(text.ToString()))).Replace("-","");
  }
  public static string FortId(Fortification fort){if(string.IsNullOrEmpty(fort.lineGroupId)){var t=fort.transform;string path="";while(t!=null){path="/"+t.name+":"+t.GetSiblingIndex()+path;t=t.parent;}fort.lineGroupId="scene:"+path;}return fort.lineGroupId;}
  public static PvpSnapshot Capture(BattleWorld w,string viewer,long tick){var snapshot=new PvpSnapshot{timeMultiplier=Time.timeScale,tick=tick,elapsed=w.Replay.Snapshot.elapsed,ended=w.SimulationEnded};
   foreach(var u in w.units){if(u==null)continue;bool own=u.ownerId==viewer,known=own||w.IsKnown(viewer,u);if(!own&&!w.IsVisible(viewer,u)&&!(!u.Alive&&w.VisibleAt(viewer,u.transform.position)))continue;
    var state=u.GetComponent<CampaignUnit>();var battery=u.GetComponent<ArtilleryBattery>();var truck=u.GetComponent<TransportTruck>();var work=w.campaign==null?null:w.campaign.lineWorks;
    snapshot.units.Add(new PvpUnit{rotating=own&&w.GetComponent<LocalCoordinatedOrders>()!=null&&w.GetComponent<LocalCoordinatedOrders>().InRotation(u),supporting=own&&w.GetComponent<LocalCoordinatedOrders>()!=null&&w.GetComponent<LocalCoordinatedOrders>().Supporting(u),links=own?w.GetComponent<LocalCoordinatedOrders>()?.NetworkLinks(u):null,artillery=known&&battery!=null?StableJson(battery.definition):null,experience=known&&u.GetComponent<UnitExperience>()!=null?u.GetComponent<UnitExperience>().Level:0,participated=own&&u.GetComponent<UnitExperience>()!=null&&u.GetComponent<UnitExperience>().PendingPromotion,marchStyle=own&&u.GetComponent<LocalMarchOrder>()!=null?(int)u.GetComponent<LocalMarchOrder>().style:1,assigned=own&&w.GetComponent<LocalPrototypeOrders>()!=null&&w.GetComponent<LocalPrototypeOrders>().IsAssigned(u),task=own?w.GetComponent<LocalPrototypeOrders>()?.Status(u):null,coordination=own?w.GetComponent<LocalCoordinatedOrders>()?.Status(u):null,id=u.unitId,owner=u.ownerId,label=w.GetComponent<StaffMapPresentation>()!=null?w.GetComponent<StaffMapPresentation>().DesignationFor(u,viewer):u.designation,capacity=known?u.Capacity:0,strengthCapacity=known?u.StrengthCapacity:0,detachment=own&&u.GetComponent<TacticalDetachment>()!=null?JsonUtility.ToJson(u.GetComponent<TacticalDetachment>()):null,position=u.transform.position,known=known,combat=known?StableJson(u.combatDefinition):null,role=known?u.combatDefinition.role:UnitRole.Infantry,echelon=known?u.combatDefinition.echelon:ArmyEchelon.Squad,personnel=known?u.Personnel:u.Alive?1:0,state=u.State,timer=own?u.StateTimer:0,working=u.Working,underFire=u.UnderFire,hidden=own&&u.HiddenInForest,ambush=own&&u.ForestAttackEnabled,point=own&&u.Point!=null?u.Point.pointId:null,carrier=own&&u.Carrier!=null?u.Carrier.Unit.unitId:null,moving=u.Motor!=null&&u.Motor.IsMoving,speed=u.Motor==null?0:u.Motor.CurrentSpeed,movementMode=u.Motor==null?MouseCommandMode.None:u.Motor.MovementMode,route=own&&u.Motor!=null?u.Motor.RemainingRoute():null,desiredSpeed=own&&state!=null?state.desiredSpeed:0,fortLevel=own&&state!=null?state.fortBuildLevel:0,cargo=own&&truck!=null?truck.Cargo:0,automatic=own&&truck!=null&&truck.Automatic,artilleryCooldown=own&&battery!=null?battery.Remaining:0,artilleryBarrageRemaining=known&&battery!=null?battery.BarrageRemaining:0,engineering=own&&work!=null?(work.IsBuilding(u)?1:work.IsDismantling(u)?2:0):0,workRemaining=own&&work!=null?work.Remaining(u):0,workApproaching=own&&work!=null&&work.Approaching(u)});
   }
   foreach(var p in w.points)if(p!=null)snapshot.cities.Add(new PvpCity{id=p.pointId,owner=p.ownerId,stock=p.ownerId==viewer?p.resourceStock:0,factory=p.hasFactory,capturing=p.CapturingPlayer,progress=p.CaptureProgress});
   var logistics=w.GetComponent<LogisticsWorld>();if(logistics!=null){foreach(var site in logistics.sites)if(site!=null)snapshot.sites.Add(new PvpSite{id=site.siteId,stock=site.stock});snapshot.production.AddRange(logistics.NetworkJobs(viewer));}
   if(w.campaign!=null)foreach(var d in w.campaign.depots)if(d!=null&&!d.Removed&&(d.ownerId==viewer||!w.fogEnabled||w.VisibleAt(viewer,d.transform.position)))snapshot.depots.Add(new PvpDepot{id=d.depotId,owner=d.ownerId,name=d.displayName,position=d.transform.position,stock=d.ownerId==viewer||d.resourcePile?d.stock:0,pile=d.resourcePile});
   var combined=w.GetComponent<CombinedArmsWorld>();if(combined!=null){foreach(var f in combined.fortifications)if(f!=null&&!f.Destroyed&&f.VisibleTo(w,viewer))snapshot.forts.Add(new PvpFort{id=FortId(f),owner=f.ownerId,position=f.transform.position,side=f.engineerSide,points=f.linePoints,level=f.level,health=f.Health,maximum=f.MaximumHealth,length=f.builtLengthMeters,radius=f.radius});}
   var production=w.GetComponent<InfantryProduction>();if(production!=null)foreach(var job in production.Jobs)if(job.owner==viewer)snapshot.production.Add(new PvpProduction{id=job.id,city=job.city.pointId,owner=job.owner,role=job.role,echelon=job.echelon,remaining=job.remaining,cost=job.paidCost});
   snapshot.recoveryQueue=FacilityRecoveryQueue.For(w)?.NetworkQueue(viewer);if(w.campaign!=null&&w.campaign.lineWorks!=null)snapshot.works=w.campaign.lineWorks.NetworkProjects(viewer);
   if(w.territory!=null)snapshot.territory=w.territory.NetworkOwners(viewer);return snapshot;
  }
  public static GameObject Prefab(UnitRole role){if(role==UnitRole.RocketArtillery||role==UnitRole.Radar)return Resources.Load<GameObject>("Radar/"+(role==UnitRole.RocketArtillery?"RocketArtillery":"Radar"));string name=role==UnitRole.Logistics?"TransportTruck":role.ToString();return Resources.Load<GameObject>("PvpUnits/"+name);}
  static BattleUnit Find(BattleWorld w,string id){foreach(var u in w.units)if(u!=null&&u.unitId==id)return u;return null;}
  public static PvpEffect FilterEffect(BattleWorld w,string viewer,CombatEffectEvent effect){var source=Find(w,effect.SourceId);var target=Find(w,effect.TargetId);bool visibleSource=effect.HasSource&&(effect.SourceOwner==viewer||!w.fogEnabled||(source!=null&&w.IsVisible(viewer,source)));bool visibleTarget=effect.TargetOwner==viewer||!w.fogEnabled||(target!=null?w.IsVisible(viewer,target):w.VisibleAt(viewer,effect.TargetPosition));if(!visibleSource&&!visibleTarget||effect.Stage==CombatEffectStage.ArtilleryLaunch&&!visibleSource||effect.Stage==CombatEffectStage.ArtilleryImpact&&!visibleTarget)return null;return new PvpEffect{stage=effect.Stage,source=visibleSource?effect.SourceId:null,sourceOwner=visibleSource?effect.SourceOwner:null,target=visibleTarget?effect.TargetId:null,targetOwner=visibleTarget?effect.TargetOwner:null,role=visibleSource&&source!=null&&w.IsKnown(viewer,source)?effect.SourceRole:UnitRole.Infantry,hasSource=visibleSource,from=visibleSource?effect.SourcePosition:Vector3.zero,to=visibleTarget?effect.TargetPosition:effect.SourcePosition,radius=effect.Radius};}
  static RecoveryPoint City(BattleWorld w,string id){foreach(var p in w.points)if(p!=null&&p.pointId==id)return p;return null;}
  static BattleUnit Spawn(BattleWorld w,PvpUnit data){var prefab=Prefab(data.role);if(prefab==null)throw new Exception("缺少联网单位预制体："+data.role);var obj=UnityEngine.Object.Instantiate(prefab);obj.name=data.label;var unit=obj.GetComponent<BattleUnit>();unit.unitId=data.id;unit.ownerId=data.owner;unit.designation=data.label;unit.combatDefinition=UnityEngine.Object.Instantiate(unit.combatDefinition);if(!string.IsNullOrEmpty(data.combat))JsonUtility.FromJsonOverwrite(data.combat,unit.combatDefinition);unit.combatDefinition.echelon=data.echelon;
   unit.NetworkDefinitionOwned=true;var mover=obj.GetComponent<ArmyRoadMover>();mover.waterMap=w.setup.freeMarchMap.waterMap;mover.terrainMap=w.setup.freeMarchMap;mover.InitializeAt(w.setup.roadMap.Network,new RoadPoint(data.position.x,data.position.y),RoadRouteView.Create(obj.transform,"联网移动路线",.06f,3,Color.cyan));var free=obj.GetComponent<ArmyFreeMarchMover>();free.Initialize(mover.Motor);free.BindMap(w.setup.freeMarchMap);w.RegisterUnit(unit,mover);var order=obj.GetComponent<AIUnitOrder>();if(order!=null)order.enabled=false;return unit;
  }
  public static void Apply(BattleWorld w,string viewer,PvpSnapshot snapshot){if(!w.Initialized)return;UnityEngine.Object.FindObjectOfType<BattleTimeControl>()?.ApplyNetworkMultiplier(snapshot.timeMultiplier);var received=new HashSet<string>();if(w.campaign!=null&&w.campaign.logistics!=null)foreach(var site in w.campaign.logistics.sites)if(site!=null)foreach(var state in snapshot.sites)if(state.id==site.siteId){site.stock=state.stock;break;}
   foreach(var data in snapshot.cities){var p=City(w,data.id);if(p==null)continue;p.ownerId=data.owner;p.resourceStock=data.stock;p.hasFactory=data.factory;p.CapturingPlayer=data.capturing;p.CaptureProgress=data.progress;}
   foreach(var data in snapshot.units){received.Add(data.id);var u=Find(w,data.id);if(u!=null&&data.known&&u.combatDefinition.role!=data.role){var keptUnits=new List<BattleUnit>(w.units);keptUnits.Remove(u);w.units=keptUnits.ToArray();var keptArmies=new List<ArmyRoadMover>(w.setup.sceneArmies);keptArmies.Remove(u.GetComponent<ArmyRoadMover>());w.setup.sceneArmies=keptArmies.ToArray();u.gameObject.SetActive(false);UnityEngine.Object.Destroy(u.gameObject);u=null;}if(u==null)u=Spawn(w,data);u.gameObject.SetActive(true);u.NetworkVisible=true;if(data.known&&!string.IsNullOrEmpty(data.combat)){if(!u.NetworkDefinitionOwned){u.combatDefinition=UnityEngine.Object.Instantiate(u.combatDefinition);u.NetworkDefinitionOwned=true;}JsonUtility.FromJsonOverwrite(data.combat,u.combatDefinition);w.Intel.Identify(viewer,u);}var split=u.GetComponent<TacticalDetachment>();if(!string.IsNullOrEmpty(data.detachment)){if(split==null)split=u.gameObject.AddComponent<TacticalDetachment>();JsonUtility.FromJsonOverwrite(data.detachment,split);}else if(split!=null)UnityEngine.Object.Destroy(split);w.GetComponent<StaffMapPresentation>()?.SetDesignation(u,data.label);u.designation=data.label;u.ApplyNetworkState(data,City(w,data.point));var experience=UnitExperience.Ensure(u);if(experience!=null)experience.ApplyNetworkState(data.experience,data.participated);var march=u.GetComponent<LocalMarchOrder>()??u.gameObject.AddComponent<LocalMarchOrder>();march.world=w;march.style=(LocalMarchStyle)Mathf.Clamp(data.marchStyle,0,2);var presentation=u.GetComponent<NetworkUnitPresentation>()??u.gameObject.AddComponent<NetworkUnitPresentation>();presentation.task=data.task;presentation.coordination=data.coordination;presentation.assigned=data.assigned;presentation.links=data.links;presentation.rotating=data.rotating;presentation.supporting=data.supporting;var state=u.GetComponent<CampaignUnit>();if(state!=null){state.desiredSpeed=data.desiredSpeed;state.fortBuildLevel=data.fortLevel;}if(u.Motor!=null)u.Motor.ApplyNetworkState(data.route,data.speed,data.movementMode,data.moving);var battery=u.GetComponent<ArtilleryBattery>();if(battery!=null)battery.ApplyNetworkState(data);var truck=u.GetComponent<TransportTruck>();if(truck!=null)truck.ApplyNetworkState(data.cargo,data.automatic);if(w.campaign!=null)w.campaign.lineWorks.ApplyNetworkWork(u,data);}
   FacilityRecoveryQueue.For(w)?.ApplyNetworkQueue(snapshot.recoveryQueue);w.GetComponent<LocalCoordinatedOrders>()?.ApplyNetworkLinks();if(w.campaign!=null)w.campaign.lineWorks.ApplyNetworkProjects(snapshot.works);
   foreach(var u in w.units)if(u!=null&&!received.Contains(u.unitId)){u.NetworkVisible=false;u.gameObject.SetActive(false);}
   foreach(var u in w.units)if(u!=null){var carrier=u.GetComponent<PersonnelCarrier>();if(carrier!=null)carrier.ClearNetworkPassengers();}
   foreach(var data in snapshot.units){var u=Find(w,data.id);var parent=Find(w,data.carrier);var carrier=parent==null?null:parent.GetComponent<PersonnelCarrier>();u.ApplyNetworkCarrier(carrier);if(carrier!=null)carrier.AddNetworkPassenger(u);}
   var logistics=w.GetComponent<LogisticsWorld>();if(logistics!=null)logistics.ApplyNetworkJobs(snapshot.production);
   if(w.campaign!=null){var ids=new HashSet<string>();foreach(var data in snapshot.depots){ids.Add(data.id);var d=w.campaign.depots.Find(item=>item!=null&&item.depotId==data.id);if(d==null){d=w.campaign.CreateDepot(data.position,data.owner,data.stock,data.pile);d.depotId=data.id;if(d.recovery!=null)d.recovery.pointId="repair:"+data.id;}d.gameObject.SetActive(true);d.stock=data.stock;d.ownerId=data.owner;d.displayName=data.name;d.transform.position=data.position;}foreach(var d in w.campaign.depots)if(d!=null&&!ids.Contains(d.depotId)){if(d.ownerId==viewer||!w.fogEnabled||w.VisibleAt(viewer,d.transform.position))d.Remove();else d.gameObject.SetActive(false);}}
   var combined=w.GetComponent<CombinedArmsWorld>();if(combined!=null){var ids=new HashSet<string>();foreach(var data in snapshot.forts){ids.Add(data.id);var f=combined.fortifications.Find(item=>item!=null&&FortId(item)==data.id);if(f==null){if(data.points!=null&&data.points.Length>1&&w.campaign!=null)f=w.campaign.lineWorks.CreateLine(data.points,data.side,data.owner,data.level,data.length);else{var go=new GameObject("联网工事");f=go.AddComponent<Fortification>();combined.fortifications.Add(f);}f.lineGroupId=data.id;}f.gameObject.SetActive(true);f.ownerId=data.owner;f.level=data.level;f.radius=data.radius;f.transform.position=data.position;f.SetFragmentHealth(data.health,data.maximum);}foreach(var f in combined.fortifications)if(f!=null&&!ids.Contains(FortId(f))){if(f.ownerId==viewer||!w.fogEnabled||w.VisibleAt(viewer,f.transform.position))f.Demolish();else f.gameObject.SetActive(false);}}
   var production=w.GetComponent<InfantryProduction>();if(production!=null)production.ApplyNetworkJobs(snapshot.production);if(w.territory!=null&&snapshot.territory!=null)w.territory.ApplyNetworkOwners(snapshot.territory);w.Replay.ApplyNetworkClock(snapshot.elapsed);w.Replay.Sample();foreach(var effect in snapshot.effects)w.NotifyCombatEffect(new CombatEffectEvent(effect.stage,effect.source,effect.sourceOwner,effect.role,effect.hasSource,effect.from,effect.target,effect.targetOwner,effect.to,effect.radius));if(snapshot.ended&&!w.SimulationEnded)w.ApplyNetworkEnd();
  }
